        or (regexp_replace(matched collate "C", '(?:בין[ ]+)?(?:[0-9]{1,2}|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty)(?:[ \t]*(?:[-–—]|to|עד|ל-?)[ \t]*(?:[0-9]{1,2}|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty))?','','i') collate "C") ~* '(?<![A-Za-z0-9_])(?:[0-9]{1,2}|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty)(?![A-Za-z0-9_])' then experience := null; exit; end if;
      select array_agg(case when m[1] ~ '^[0-9]+$' then m[1]::integer
        else array_position(array['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen', 'twenty']::text[],lower(m[1])) - 1 end)
        into amounts from regexp_matches(matched collate "C", '(?<![A-Za-z0-9_])((?:[0-9]{1,2}|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty))(?![A-Za-z0-9_])','gi') m;
      if amounts[1] is null or (array_length(amounts,1) > 1 and amounts[2] < amounts[1]) then experience := null; exit; end if;
      quoted := regexp_replace(matched collate "C", '^minimum(?:[ \t]+of)?[ \t]+','','i');
      rank := case when section = 'applicant' then 2 else 0 end + case when (clause collate "C") ~* '(?:(?<![A-Za-z0-9_])(?=[A-Za-z0-9_])|(?<=[A-Za-z0-9_])(?![A-Za-z0-9_]))overall(?:(?<![A-Za-z0-9_])(?=[A-Za-z0-9_])|(?<=[A-Za-z0-9_])(?![A-Za-z0-9_]))|(?:(?<![A-Za-z0-9_])(?=[A-Za-z0-9_])|(?<=[A-Za-z0-9_])(?![A-Za-z0-9_]))(?:software|engineering|development|developer|programming|professional|industry|relevant|commercial|automation|platform|robotics|embedded|simulation)[ -]+(?:[a-z-]+[ ]+){0,3}experience(?:(?<![A-Za-z0-9_])(?=[A-Za-z0-9_])|(?<=[A-Za-z0-9_])(?![A-Za-z0-9_]))|(?:(?<![A-Za-z0-9_])(?=[A-Za-z0-9_])|(?<=[A-Za-z0-9_])(?![A-Za-z0-9_]))experience[ ]+(?:as[ ]+(?:a[ ]+)?(?:software[ ]+)?(?:engineer|developer)|in[ ]+(?:software|engineering|development))(?:(?<![A-Za-z0-9_])(?=[A-Za-z0-9_])|(?<=[A-Za-z0-9_])(?![A-Za-z0-9_]))|נ[י]?סיון[ ]+בפיתוח|(?:(?<![A-Za-z0-9_])(?=[A-Za-z0-9_])|(?<=[A-Za-z0-9_])(?![A-Za-z0-9_]))years?(?:[ ]+of)?[ ]+experience(?:[ ]+(?:is[ ]+)?required)?[ ]*$' then 1 else 0 end;
      if rank > selected_rank then
        selected_rank := rank; selected_minimum := amounts[1]; disagreement := false;
        experience := substr(description,clause_start + end_at - length(quoted) - 1,length(quoted));
      elsif rank = selected_rank and amounts[1] <> selected_minimum then disagreement := true; end if;
    end loop;
  end if;
  if disagreement then experience := null; end if;
  return jsonb_build_object('stack',technologies,'experience',experience,
    'description_available',coalesce((description collate "C") ~ '[^ \t\n\r\f\v\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]',false));
end
$fn$;
revoke all on function public.posting_list_metadata(text) from public, anon, authenticated;
grant execute on function public.posting_list_metadata(text) to service_role;
